WITH base AS (SELECT id, customer_id, device, browser, country, CASE WHEN device IN ('tablet', 'desktop') THEN 'Core' ELSE 'Other' END AS device_group, DATE_TRUNC('MONTH', started_at) AS started_at_period, COALESCE(country, 'UNKNOWN') AS country_clean FROM sessions WHERE started_at >= DATE '2023-07-17'), with_gaps AS (SELECT *, CASE WHEN LAG(started_at_period) OVER (PARTITION BY device ORDER BY started_at_period, id) IS NULL OR started_at_period > LAG(started_at_period) OVER (PARTITION BY device ORDER BY started_at_period, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM base), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device ORDER BY started_at_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT session_id, DATE_TRUNC('YEAR', started_at_period) AS year_start, COUNT(CASE WHEN country = 'JP' THEN 1 END) AS jp_count, COUNT(CASE WHEN browser = 'Edge' THEN 1 END) AS edge_count, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM islands GROUP BY CUBE (session_id, DATE_TRUNC('YEAR', started_at_period)) ORDER BY year_start
